export class TagsService {
    /**
     * Read Tags
     *
     * Retrieve the caller's tags, each with the number of tasks carrying it
     * (FR-01.26). Also what autocomplete offers while a tag is typed: `q` by
     * the start of the name, `near` by the names it would read the same as.
     *
     * A bot user reads its owner's whole vocabulary, counts included, whatever
     * its scope: tags belong to the user rather than to a project, so a scope
     * has nothing to narrow them by (ADR-0003). The counts are the owner's for
     * every caller — narrowing them per caller would make one tag mean two
     * different things, which is the split ADR-0003 refused. `task_count` is
     * the live tasks, as the task list filtered by the tag shows them;
     * `archived_task_count` is those archived with their project, which are
     * counted but not reachable from here (FR-05.13).
     */
    public static readTags<ThrowOnError extends boolean = true>(options?: Options<tagsReadTagsData, ThrowOnError>) {
        return (options?.client ?? client).get<tagsReadTagsResponses, tagsReadTagsErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/tags/',
            ...options
        });
    }
    
    /**
     * Create Tag
     *
     * Create a tag on its own, before any task carries it (FR-01.20). It stays
     * until it is deleted (FR-01.23).
     *
     * A bot user needs the permission to create tags (FR-08.9).
     */
    public static createTag<ThrowOnError extends boolean = true>(options: Options<tagsCreateTagData, ThrowOnError>) {
        return (options.client ?? client).post<tagsCreateTagResponses, tagsCreateTagErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/tags/',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
    
    /**
     * Read Tag Duplicates
     *
     * The user's tags grouped where their names differ only in letter case,
     * separators, surrounding or repeated whitespace, or a trailing plural:
     * suggestions to merge, over the whole vocabulary (FR-01.28).
     *
     * Nothing here merges anything, and a group the user dismissed stays out
     * until one of its members is renamed or another spelling joins it. Like
     * merging, it is a human's tool for repairing their vocabulary.
     */
    public static readTagDuplicates<ThrowOnError extends boolean = true>(options?: Options<tagsReadTagDuplicatesData, ThrowOnError>) {
        return (options?.client ?? client).get<tagsReadTagDuplicatesResponses, unknown, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/tags/duplicates',
            ...options
        });
    }
    
    /**
     * Dismiss Tag Duplicates
     *
     * Stop offering one group of likely duplicates. The ids have to be exactly a
     * group currently offered: dismissing is a decision about the group the user
     * was shown, not about any tags that happen to be named alike.
     */
    public static dismissTagDuplicates<ThrowOnError extends boolean = true>(options: Options<tagsDismissTagDuplicatesData, ThrowOnError>) {
        return (options.client ?? client).post<tagsDismissTagDuplicatesResponses, tagsDismissTagDuplicatesErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/tags/duplicates/dismiss',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
    
    /**
     * Delete Tag
     *
     * Delete a tag and take it off every task carrying it (FR-01.25).
     *
     * There is no undoing it: a tag deletion is not a deletion event, so the
     * activity log records it but cannot restore it.
     */
    public static deleteTag<ThrowOnError extends boolean = true>(options: Options<tagsDeleteTagData, ThrowOnError>) {
        return (options.client ?? client).delete<tagsDeleteTagResponses, tagsDeleteTagErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/tags/{tag_id}',
            ...options
        });
    }
    
    /**
     * Read Tag
     *
     * Retrieve one tag by its id, with the number of tasks carrying it: what the
     * tag's panel is addressed by, so a link opens a tag the list in view would
     * exclude.
     */
    public static readTag<ThrowOnError extends boolean = true>(options: Options<tagsReadTagData, ThrowOnError>) {
        return (options.client ?? client).get<tagsReadTagResponses, tagsReadTagErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/tags/{tag_id}',
            ...options
        });
    }
    
    /**
     * Rename Tag
     *
     * Rename a tag: every task carrying it shows the new name (FR-01.24). Names
     * are case-sensitive, so changing only the case is a rename like any other.
     * Renaming a tag to the name it already has changes nothing.
     */
    public static renameTag<ThrowOnError extends boolean = true>(options: Options<tagsRenameTagData, ThrowOnError>) {
        return (options.client ?? client).patch<tagsRenameTagResponses, tagsRenameTagErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/tags/{tag_id}',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
    
    /**
     * Preview Tag Merge
     *
     * How many tasks merging `source_ids` into this tag would change, each
     * counted once, with those archived with their project apart: what the
     * merge confirmation says before anything happens (FR-01.27).
     */
    public static previewTagMerge<ThrowOnError extends boolean = true>(options: Options<tagsPreviewTagMergeData, ThrowOnError>) {
        return (options.client ?? client).get<tagsPreviewTagMergeResponses, tagsPreviewTagMergeErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/tags/{tag_id}/merge-preview',
            ...options
        });
    }
    
    /**
     * Merge Tags
     *
     * Fold other tags into this one: every task carrying one of them carries
     * this tag instead, once, and they are deleted (FR-01.27).
     *
     * Renaming a tag to a name in use stays refused; this is the separate,
     * deliberate act for putting two spellings together. It keeps names as they
     * are — case-sensitive and unique per user — and, like deleting a tag,
     * cannot be undone: the activity log records it without being able to
     * restore it. Only a human merges, as only a human renames or deletes a tag
     * (ADR-0003).
     */
    public static mergeTags<ThrowOnError extends boolean = true>(options: Options<tagsMergeTagsData, ThrowOnError>) {
        return (options.client ?? client).post<tagsMergeTagsResponses, tagsMergeTagsErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/tags/{tag_id}/merge',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
}

export class ActivityService {
    /**
     * Read Activity Log
     *
     * Retrieve the current user's activity log, newest first.
     *
     * `actor_bot_user_id` narrows it to one bot user's own changes — what an
     * operator asks when they want to read an integration rather than their
     * whole account (FR-10.2). A deleted bot user's entries stay readable under
     * it (FR-08.19).
     *
     * Always the requesting user's own entries and nothing wider: there is no
     * parameter or role that reaches another user's log, the superuser's
     * included (FR-10.7). Narrowing by a bot user somebody else owns is
     * therefore an empty feed rather than a refusal — the caller's own entries,
     * of which that actor made none — so the filter says nothing about whose
     * bot user it is, or whether it exists at all.
     */
    public static readActivityLog<ThrowOnError extends boolean = true>(options?: Options<activityReadActivityLogData, ThrowOnError>) {
        return (options?.client ?? client).get<activityReadActivityLogResponses, activityReadActivityLogErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/activity-log/',
            ...options
        });
    }
    
    /**
     * Restore From Activity Entry
     *
     * Restore what a deletion entry records as deleted (FR-10.4).
     *
     * The deletion entry is the handle: there is no trash to restore from. What
     * comes back is exactly what went down in that deletion — a task with its
     * subtasks (FR-01.10), or a project with its tasks (FR-05.9) — so anything
     * deleted on its own before stays deleted. A restore is refused, with a code
     * naming the cause, when it has nowhere to come back to. Restoring what is
     * already back changes nothing.
     */
    public static restoreFromActivityEntry<ThrowOnError extends boolean = true>(options: Options<activityRestoreFromActivityEntryData, ThrowOnError>) {
        return (options.client ?? client).post<activityRestoreFromActivityEntryResponses, activityRestoreFromActivityEntryErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/activity-log/{entry_id}/restore',
            ...options
        });
    }
}

export class BotsService {
    /**
     * Read Bot Users
     *
     * Retrieve the current user's bot users, with their scopes, oldest first.
     * Deleted bot users are not among them.
     */
    public static readBotUsers<ThrowOnError extends boolean = true>(options?: Options<botsReadBotUsersData, ThrowOnError>) {
        return (options?.client ?? client).get<botsReadBotUsersResponses, botsReadBotUsersErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/bot-users/',
            ...options
        });
    }
    
    /**
     * Create Bot User
     *
     * Create a bot user with its scope: the projects it may act in, each named
     * explicitly (FR-08.6), and what it may do there (FR-08.9, FR-08.10).
     *
     * It has no token yet; issuing one is a step of its own.
     */
    public static createBotUser<ThrowOnError extends boolean = true>(options: Options<botsCreateBotUserData, ThrowOnError>) {
        return (options.client ?? client).post<botsCreateBotUserResponses, botsCreateBotUserErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/bot-users/',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
    
    /**
     * Delete Bot User
     *
     * Delete a bot user (FR-08.18). It is marked deleted rather than removed, so
     * what it did and what it was assigned still name it (FR-08.19, FR-08.21),
     * and its token is refused from the next request on (FR-08.20).
     *
     * There is no undoing it, and nothing here acts on it again: every endpoint
     * that would change a bot user refuses a deleted one, and the list leaves it
     * out. Reading it by its id still works, so what it did can still be read
     * back to the bot user that did it.
     */
    public static deleteBotUser<ThrowOnError extends boolean = true>(options: Options<botsDeleteBotUserData, ThrowOnError>) {
        return (options.client ?? client).delete<botsDeleteBotUserResponses, botsDeleteBotUserErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/bot-users/{bot_user_id}',
            ...options
        });
    }
    
    /**
     * Read Bot User
     *
     * Retrieve one bot user by its id, with its scope: what the bot user's panel
     * is addressed by.
     *
     * A deleted bot user reads here too, marked deleted. It is kept rather than
     * removed precisely so that what it did still names it (FR-08.19), and a
     * reader following one of those references has to land on a record that
     * says what it now is — while every endpoint that would change it still
     * refuses, and the list still leaves it out.
     */
    public static readBotUser<ThrowOnError extends boolean = true>(options: Options<botsReadBotUserData, ThrowOnError>) {
        return (options.client ?? client).get<botsReadBotUserResponses, botsReadBotUserErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/bot-users/{bot_user_id}',
            ...options
        });
    }
    
    /**
     * Update Bot User
     *
     * Rename a bot user, or replace its scope, or both. The bot user's next
     * request is authorized against the new scope; its token is untouched.
     *
     * As on creation, every project has to be one of the user's own.
     */
    public static updateBotUser<ThrowOnError extends boolean = true>(options: Options<botsUpdateBotUserData, ThrowOnError>) {
        return (options.client ?? client).patch<botsUpdateBotUserResponses, botsUpdateBotUserErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/bot-users/{bot_user_id}',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
    
    /**
     * Revoke Bot User Token
     *
     * Revoke the bot user's token: the next request with it is refused
     * (FR-08.15). The bot user keeps its name and scope, and stays without a
     * token until one is issued again.
     *
     * Revoking a bot user that holds no token changes nothing.
     */
    public static revokeBotUserToken<ThrowOnError extends boolean = true>(options: Options<botsRevokeBotUserTokenData, ThrowOnError>) {
        return (options.client ?? client).delete<botsRevokeBotUserTokenResponses, botsRevokeBotUserTokenErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/bot-users/{bot_user_id}/token',
            ...options
        });
    }
    
    /**
     * Issue Bot User Token
     *
     * Issue the bot user's token, optionally with an expiry (FR-08.14).
     *
     * This response is the only place the token appears: only its digest is
     * stored, and no endpoint returns it again (FR-08.13). A bot user that
     * already holds a token — even an expired one — is refused another until
     * that one is revoked (FR-08.16).
     */
    public static issueBotUserToken<ThrowOnError extends boolean = true>(options: Options<botsIssueBotUserTokenData, ThrowOnError>) {
        return (options.client ?? client).post<botsIssueBotUserTokenResponses, botsIssueBotUserTokenErrors, ThrowOnError>({
            responseType: 'json',
            security: [{ scheme: 'bearer', type: 'http' }],
            url: '/api/v1/bot-users/{bot_user_id}/token',
            ...options,
            headers: {
                'Content-Type': 'application/json',
                ...options.headers
            }
        });
    }
}

